# END GENERATED BY build.py


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def embedded(name: str) -> bytes:
    """One of the files build.py embedded, checked against its SHA-256."""
    if name not in BLOBS:
        raise ValueError('this patch.py has no built editor; run build.py first')
    data = zlib.decompress(base64.b64decode(''.join(BLOBS[name])))
    if sha256(data) != BLOB_SHA256[name]:
        raise ValueError('embedded file is damaged: ' + name)
    return data


# The game's disks: a "Sensi disk" directory on track 2 lists each file by
# its first track and sector; every 512-byte sector holds 510 bytes of the
# file and the track and sector of the next one.

def sensi_file(image: bytes, name: str) -> bytes:
    if image[0x2C00:0x2C0A] != b'Sensi disk':
        raise ValueError('disk 1 has no game directory')
    count = struct.unpack_from('>I', image, 0x2C18)[0]
    for index in range(1, min(count, 175) + 1):
        record = image[0x2C00 + index * 32:0x2C20 + index * 32]
        if record[:16].split(b'\0', 1)[0] != name.encode('ascii'):
            continue
        track, sector, remaining = struct.unpack_from('>BBI', record, 26)
        data, seen = bytearray(), set()
        while remaining:
            if not (0 <= track < 160 and 0 <= sector < 11) or (track, sector) in seen:
                raise ValueError('damaged file chain: ' + name)
            seen.add((track, sector))
            offset = (track * 11 + sector) * 512
            take = min(remaining, 510)
            data += image[offset:offset + take]
            remaining -= take
            track, sector = image[offset + 510:offset + 512]
        return bytes(data)
    raise ValueError('disk 1 does not hold ' + name)


# Rob Northen Compression, method 1: the game's main program is packed with it.

def crc16(data: bytes) -> int:
    result = 0
    for byte in data:
        result ^= byte
        for _ in range(8):
            result = (result >> 1) ^ (0xA001 if result & 1 else 0)
    return result


class BitStream:
    """Little-endian words, consumed from the least significant bit."""

    def __init__(self, data: bytes):
        self.data, self.cursor, self.bits, self.count = data, 0, 0, 0

    def read(self, count: int) -> int:
        while self.count < count:
            if self.cursor >= len(self.data):
                raise ValueError('RNC: truncated control bits')
            self.bits |= int.from_bytes(self.data[self.cursor:self.cursor + 2], 'little') << self.count
            self.cursor += 2
            self.count += 16
        value = self.bits & ((1 << count) - 1)
        self.bits >>= count
        self.count -= count
        return value

    def literals(self, count: int) -> bytes:
        if self.cursor + count > len(self.data):
            raise ValueError('RNC: truncated literals')
        result = self.data[self.cursor:self.cursor + count]
        self.cursor += count
        return result

    def table(self) -> dict:
        count = self.read(5)
        if count > 16:
            raise ValueError('RNC: Huffman alphabet exceeds 16 symbols')
        lengths = [self.read(4) for _ in range(count)]
        result, code = {}, 0
        for length in range(1, 16):
            code <<= 1
            for symbol, size in enumerate(lengths):
                if size == length:
                    if code >= 1 << length:
                        raise ValueError('RNC: oversubscribed Huffman table')
                    result[length, code] = symbol
                    code += 1
        return result

    def value(self, table: dict) -> int:
        code = 0
        for length in range(1, 16):
            code = (code << 1) | self.read(1)
            symbol = table.get((length, code))
            if symbol is not None:
                return symbol if symbol < 2 else (1 << (symbol - 1)) | self.read(symbol - 1)
        raise ValueError('RNC: invalid Huffman code')


def rnc_unpack(data: bytes) -> bytes:
    if len(data) < 18 or data[:4] != b'RNC\x01':
        raise ValueError('expected an RNC method-1 stream')
    size, packed, size_crc, packed_crc, _, blocks = struct.unpack_from('>IIHHBB', data, 4)
    payload = data[18:18 + packed]
    if packed > len(data) - 18 or crc16(payload) != packed_crc:
        raise ValueError('RNC: packed data damaged')
    stream = BitStream(payload)
    if stream.read(2):
        raise ValueError('RNC: locked streams are not supported')
    output = bytearray()
    for _ in range(blocks):
        literal, distance, length = (stream.table() for _ in range(3))
        runs = stream.read(16)
        for run in range(runs):
            count = stream.value(literal)
            if len(output) + count > size:
                raise ValueError('RNC: output too long')
            output += stream.literals(count)
            if run != runs - 1:
                back = stream.value(distance) + 1
                count = stream.value(length) + 2
                if back > len(output) or len(output) + count > size:
                    raise ValueError('RNC: invalid back-reference')
                for _ in range(count):
                    output.append(output[-back])
    if len(output) != size or crc16(output) != size_crc:
        raise ValueError('RNC: unpacked data damaged')
    return bytes(output)


# The install.

def verified_disks(paths: list) -> dict[int, bytes]:
    images = {}
    for path in paths:
        data = Path(path).read_bytes()
        number = DISKS.get(sha256(data))
        if number is None:
            raise ValueError('not a supported disk image: ' + str(path))
        if number in images:
            raise ValueError('the same disk was given twice: ' + str(path))
        images[number] = data
    if sorted(images) != [1, 2, 3]:
        raise ValueError('give the images of all three disks')
    return images


def build_main(disk1: bytes) -> bytes:
    """Main.bin: the game's main program from disk 1 with the editor's
    patches and the resident appended."""
    original = rnc_unpack(sensi_file(disk1, MAIN['name']))
    if len(original) != MAIN['bytes'] or sha256(original) != MAIN['sha256']:
        raise ValueError('unsupported version of the main program ' + MAIN['name'])
    result = bytearray(original)
    for name, offset, length, expected, replacement in PATCHES:
        if sha256(original[offset:offset + length]) != expected:
            raise ValueError('the main program differs at the patch ' + name)
        if replacement is not None:
            result[offset:offset + length] = bytes.fromhex(replacement)
    extension = bytearray(MAIN['extension_bytes'])
    resident = embedded('resident')
    extension[MAIN['resident_offset']:MAIN['resident_offset'] + len(resident)] = resident
    result += extension
    if len(result) != MAIN['output_bytes']:
        raise ValueError('the patched main program has the wrong size')
    return bytes(result)


def checked_module(data: bytes, identity: int, load_base: int, capacity: int) -> bytes:
    """An overlay module's header: CFMO, ABI 2, its identity, load address,
    size, entry point and the CRC-32 of its body."""
    magic, abi, header, ident, base, size, entry, crc, flags = struct.unpack_from('>4sHH6I', data)
    if ((magic, abi, header) != (b'CFMO', 2, 32) or ident != identity or base != load_base
            or size != len(data) or size > capacity or size & 1 or flags
            or not header <= entry < size or entry & 1 or zlib.crc32(data[header:]) != crc):
        raise ValueError('damaged editor module')
    return data


def blank_save_disk() -> bytes:
    """SaveDisk as the game's FORMAT leaves it: 160 tracks of 6144 bytes,
    the cfdisk directory on track 2, tracks 0, 1, 2 and 81 reserved, and the
    one-sector CFSDISK marker file."""
    tracks = [bytearray(12 * 512) for _ in range(160)]
    directory = tracks[2]
    directory[:6] = b'cfdisk'
    struct.pack_into('>I', directory, 24, 1)
    directory[32:47] = b'CFSDISK'.ljust(15, b'\0')
    directory[58:60] = bytes((3, 0))
    struct.pack_into('>I', directory, 60, 1)
    bitmap = [0xFFF if track in (0, 1, 2, 81) else 0 for track in range(160)]
    bitmap[3] = 1
    struct.pack_into('>160H', directory, 0x16A0, *bitmap)
    directory[0x17E0:] = b'\xff' * 32
    return b''.join(tracks)


def encode_marker(name: str, disk_id: bytes) -> bytes:
    """CFEDITOR: the name the editor shows for Custom and a random identity."""
    if not 1 <= len(name) <= 31 or any(not 0x20 <= ord(char) <= 0x7E for char in name):
        raise ValueError('the name must have 1 to 31 printable ASCII characters')
    if len(disk_id) != 16 or not any(disk_id):
        raise ValueError('invalid identity')
    body = disk_id + name.encode('ascii').ljust(32, b'\0')
    return struct.pack('>4sHHII', b'CFDI', 1, 16, len(body), zlib.crc32(body)) + body


def decode_marker(data: bytes) -> str:
    if (len(data) != 64 or struct.unpack_from('>4sHHI', data) != (b'CFDI', 1, 16, 48)
            or zlib.crc32(data[16:]) != struct.unpack_from('>I', data, 12)[0]):
        raise ValueError('the editor marker CFEDITOR is damaged')
    name = data[32:].split(b'\0', 1)[0]
    try:
        text = name.decode('ascii')
        if encode_marker(text, data[16:32]) != data:
            raise ValueError
    except ValueError:
        raise ValueError('the editor marker CFEDITOR is damaged') from None
    return text


def icon(slave_name: str) -> bytes:
    """A Workbench project icon whose default tool is WHDLoad."""
    rows = ICON_PICTURE.splitlines()
    width, height = len(rows[0]), len(rows)
    words = (width + 15) // 16
    planes = []
    for plane in (1, 2):
        data = bytearray()
        for row in rows:
            bits = 0
            for x in range(words * 16):
                colour = '.kwb'.index(row[x]) if x < width else 0
                bits = bits << 1 | (colour & plane != 0)
            data += bits.to_bytes(words * 2, 'big')
        planes.append(bytes(data))

    def string(text: str) -> bytes:
        data = text.encode('ascii') + b'\0'
        return struct.pack('>I', len(data)) + data

    no_position = 0x80000000
    disk_object = struct.pack(
        '>HH' 'IhhhhHHH' 'IIIIIHI' 'BB' 'IIIIIII',
        0xE310, 1,                                  # magic, version
        0, 0, 0, width, height + 1, 4, 3, 1,        # gadget: size, image, boolean
        1, 0, 0, 0, 0, 0, 0,                        # gadget render image only
        4, 0,                                       # WBPROJECT
        1, 1, no_position, no_position, 0, 0, 10240)
    image = struct.pack('>hhhhhIBBI', 0, 0, width, height, 2, 1, 3, 0, 0)
    tooltypes = [f'SLAVE={slave_name}'] + ICON_TOOLTYPES
    return (disk_object + image + b''.join(planes) + string('WHDLoad')
            + struct.pack('>I', (len(tooltypes) + 1) * 4) + b''.join(string(t) for t in tooltypes))


def prepare_install(images: dict[int, bytes], name: str = 'CUSTOM LEVELS',
                    disk_id: bytes | None = None) -> dict[str, bytes]:
    """The install's files by relative path."""
    files = {SLAVE: embedded(SLAVE), 'CannonFodder.info': icon(SLAVE),
             'Main.bin': build_main(images[1]),
             'Disk.1': images[1], 'Disk.2': images[2], 'Disk.3': images[3],
             'SaveDisk': blank_save_disk(),
             f'{CUSTOM}/{MARKER_NAME}': encode_marker(
                 name, secrets.token_bytes(16) if disk_id is None else disk_id)}
    for filename, identity, load_base, capacity in MODULES:
        files[f'{CUSTOM}/{filename}'] = checked_module(embedded(filename), identity,
                                                       load_base, capacity)
    return files


# Missions. A mission is a manifest gggggggg.cmi (CFMI: a 16-byte header and
# JSON) and per phase a map ggggggggNN.map and an object list ggggggggNN.spt,
# where gggggggg is the mission's generation and NN the phase.

MISSION_SCHEMA = 'cannon-fodder-custom-mission-v1'
ROOT_KEYS = {'schema', 'id', 'revision', 'title', 'initial_recruits', 'phases'}
PHASE_KEYS = {'title', 'map', 'spt', 'objectives', 'aggression', 'new_recruit_rank',
              'grenades_per_troop', 'rockets_per_troop', 'enemy_grenades', 'overview', 'countdown'}
HEX8 = re.compile(r'[0-9A-F]{8}')
NAME_CHARS = frozenset('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-')
RESOURCE_PAIRS = frozenset((
    ('junbase', 'junsub0'), ('junbase', 'junsub1'), ('icebase', 'icesub0'),
    ('desbase', 'dessub0'), ('morbase', 'morsub0'), ('intbase', 'intsub0'),
))
# The objects that need companion records right after them (vehicles with
# their shadows and turrets, buildings with their doors).
COMPANIONS = {
    **dict.fromkeys((0x28, 0x2A, 0x2B, 0x2C, 0x6B), (4, 4, 0x29)),
    **dict.fromkeys((0x31, 0x32, 0x33, 0x34, 0x65, 0x66, 0x67, 0x68), (4, 4)),
    **dict.fromkeys((0x45, 0x50, 0x51, 0x52), (4, 0x29)),
    **dict.fromkeys((0x3C, 0x3F, 0x40, 0x41), (4,)),
    **dict.fromkeys((0x54, 0x55, 0x69, 0x6A), (0x29,)),
}
COUNTED_TYPES = frozenset((0, 0x05, 0x24, 0x48, 0x6A))
PRIMARY_TYPES = (frozenset((0, 0x05, 0x24, 0x3D, 0x3E, 0x46, 0x48, 0x4E, 0x4F, 0x53, 0x63))
                 | (COMPANIONS.keys() - {0x3C}))
BUILDING_TYPES = frozenset((0x14, 0x19, 0x58, 0x64, 0x6C, 0x6D, 0x6E))
ENEMY_TYPES = frozenset((0x05, 0x24, 0x28, 0x2A, 0x2B, 0x2C, 0x45, 0x50, 0x51, 0x52, 0x54, 0x55, 0x69))


def valid_name(name: str) -> bool:
    return 1 <= len(name) <= 14 and all(char in NAME_CHARS for char in name)


def _keys(value, expected: set, field: str) -> None:
    if not isinstance(value, dict) or set(value) != expected:
        raise ValueError(f'{field} must be an object with exactly: {", ".join(sorted(expected))}')


def _integer(value, low: int, high: int, field: str) -> None:
    if type(value) is not int or not low <= value <= high:
        raise ValueError(f'{field} must be an integer in {low}..{high}')


def _hex8(value, field: str) -> None:
    if not isinstance(value, str) or HEX8.fullmatch(value) is None:
        raise ValueError(f'{field} must be eight uppercase hexadecimal characters')


def _title(value, field: str) -> None:
    if (not isinstance(value, str) or not 1 <= len(value) <= 63
            or any(not 0x20 <= ord(char) <= 0x7E for char in value)):
        raise ValueError(f'{field} must contain 1..63 printable ASCII characters')


def validate_manifest(value, manifest_name: str) -> None:
    if re.fullmatch(r'[0-9a-f]{8}\.cmi', manifest_name) is None:
        raise ValueError('manifest filename must be gggggggg.cmi with lowercase hexadecimal generation')
    generation = manifest_name[:8]
    _keys(value, ROOT_KEYS, 'manifest')
    if value['schema'] != MISSION_SCHEMA:
        raise ValueError(f'schema must be {MISSION_SCHEMA}')
    _hex8(value['id'], 'id')
    _integer(value['revision'], 0, 65535, 'revision')
    _title(value['title'], 'title')
    _integer(value['initial_recruits'], 1, 32767, 'initial_recruits')
    phases = value['phases']
    if not isinstance(phases, list) or not 1 <= len(phases) <= 6:
        raise ValueError('phases must be an array of 1..6 records')
    for index, phase in enumerate(phases):
        field = f'phases[{index}]'
        _keys(phase, PHASE_KEYS, field)
        _title(phase['title'], field + '.title')
        for kind, maximum in (('map', 15096), ('spt', 430)):
            reference = phase[kind]
            ref_field = field + '.' + kind
            _keys(reference, {'name', 'length', 'crc32'}, ref_field)
            expected = f'{generation}{index:02x}.{kind}'
            if reference['name'] != expected:
                raise ValueError(f'{ref_field}.name must be {expected}')
            _integer(reference['length'], 1, maximum, ref_field + '.length')
            _hex8(reference['crc32'], ref_field + '.crc32')
        objectives = phase['objectives']
        if not isinstance(objectives, list) or not 1 <= len(objectives) <= 8:
            raise ValueError(field + '.objectives must be a nonempty array of distinct IDs 1..8')
        for objective in objectives:
            _integer(objective, 1, 8, field + '.objectives ID')
        if len(set(objectives)) != len(objectives):
            raise ValueError(field + '.objectives contains duplicate IDs')
        aggression = phase['aggression']
        _keys(aggression, {'minimum', 'maximum'}, field + '.aggression')
        for bound in ('minimum', 'maximum'):
            _integer(aggression[bound], 0, 20, field + '.aggression.' + bound)
        if aggression['minimum'] > aggression['maximum']:
            raise ValueError(field + '.aggression minimum exceeds maximum')
        _integer(phase['new_recruit_rank'], 0, 7, field + '.new_recruit_rank')
        _integer(phase['grenades_per_troop'], 0, 2, field + '.grenades_per_troop')
        if phase['grenades_per_troop'] == 1:
            raise ValueError(field + '.grenades_per_troop must be 0 or 2')
        _integer(phase['rockets_per_troop'], 0, 1, field + '.rockets_per_troop')
        for key in ('enemy_grenades', 'overview'):
            if type(phase[key]) is not bool:
                raise ValueError(field + '.' + key + ' must be a boolean')
        if phase['countdown'] is not None and phase['countdown'] != 'original-final-map':
            raise ValueError(field + '.countdown must be null or original-final-map')


def _json_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f'duplicate JSON key: {key}')
        result[key] = value
    return result


def _json_integer(token: str) -> int:
    if token.startswith('-'):
        raise ValueError('negative JSON numbers are not allowed')
    return int(token)


def _json_reject(token: str):
    raise ValueError(f'non-integer JSON number is not allowed: {token}')


def decode_manifest(data: bytes, manifest_name: str) -> dict:
    if not 17 <= len(data) <= 4096:
        raise ValueError('manifest file length must be 17..4096 bytes')
    magic, version, header, size, checksum = struct.unpack_from('>4sHHII', data)
    if magic != b'CFMI':
        raise ValueError('manifest magic must be CFMI')
    if version != 1:
        raise ValueError('unsupported CFMI version')
    if header != 16:
        raise ValueError('CFMI header size must be 16')
    if not 1 <= size <= 4080 or len(data) != 16 + size:
        raise ValueError('CFMI body length disagrees with exact file length')
    body = data[16:]
    if zlib.crc32(body) != checksum:
        raise ValueError('CFMI body CRC-32 mismatch')
    try:
        value = json.loads(body.decode('ascii'), object_pairs_hook=_json_object,
                           parse_int=_json_integer, parse_float=_json_reject,
                           parse_constant=_json_reject)
    except (UnicodeDecodeError, RecursionError) as error:
        raise ValueError('JSON must be ASCII with schema-bounded nesting') from error
    validate_manifest(value, manifest_name)
    return value


def decode_map(data: bytes) -> dict:
    """A MAP file: two 16-byte tileset names, 'cfed', the width and height in
    cells and then one word per cell."""
    if len(data) < 96:
        raise ValueError('MAP header is shorter than 96 bytes')
    width, height = struct.unpack_from('>HH', data, 84)
    if not width or not height:
        raise ValueError('MAP dimensions must be nonzero')
    if len(data) != 96 + width * height * 2:
        raise ValueError('MAP length does not match header dimensions')
    if data[80:84] != b'cfed':
        raise ValueError('MAP cfed signature missing')
    names = []
    for slot in (data[:16], data[16:32]):
        if b'\0' not in slot:
            raise ValueError('tileset name is not NUL-terminated in its 16-byte slot')
        names.append(slot.split(b'\0', 1)[0].decode('ascii'))
    values = [value for (value,) in struct.iter_unpack('>H', data[96:])]
    return {'tilesets': names, 'width': width, 'height': height, 'cells': values}


def decode_spt(data: bytes) -> list[dict]:
    """An SPT file: ten bytes per object, the last three words X, Y, type."""
    if len(data) % 10:
        raise ValueError('SPT length must be a multiple of ten')
    return [{'x': x, 'y': y, 'type': kind} for _, _, x, y, kind in struct.iter_unpack('>5H', data)]


def gameplay_issues(phase: dict, level: dict, objects: list[dict]) -> list[str]:
    """The severities of what the editor's Check reports for one phase:
    'error' blocks Test and Play, 'review' asks for a test."""
    issues = []
    width, height, cells = level['width'], level['height'], level['cells']
    if width < 19 or height < 15:
        issues.append('error')
    if any((word & 0x1FF) > 399 for word in cells):
        issues.append('error')
    if any((word & 0x1FF) == 399 for word in cells):
        issues.append('review')
    if any(word & 0x1E00 for word in cells):
        issues.append('review')
    markers = [word >> 13 for word in cells if word >> 13]
    if len(markers) > 10:
        issues.append('error')
    if any(marker >= 5 for marker in markers):
        issues.append('review')
    if any(marker in (1, 2, 3, 5, 6, 7) for marker in markers):
        issues.append('review')
    active = [((obj['x'] + 16) & 0xFFFF) < 0x8000 for obj in objects]
    types = [obj['type'] for obj in objects]
    companions = set()
    for record, kind in enumerate(types):
        suffix = COMPANIONS.get(kind)
        if suffix is None:
            continue
        end = record + 1 + len(suffix)
        if tuple(types[record + 1:end]) != suffix:
            issues.append('error')
        elif active[record]:
            companions.update(range(record + 1, end))
        if end > 43:
            issues.append('error')
        if kind in PRIMARY_TYPES and end > 30:
            issues.append('error')
    for record, obj in enumerate(objects):
        x, y, kind = obj['x'], obj['y'], obj['type']
        if (x + 16) & 0xFFFF == 0xFFFF:
            issues.append('error')
        elif x == 0x8000:
            if kind not in (0x04, 0x29) or record not in companions:
                issues.append('error')
        elif x > 0x7FEF:
            issues.append('error')
        if not active[record] and kind in COUNTED_TYPES:
            issues.append('error')
        if active[record]:
            if y >= 0x8000:
                issues.append('error')
            elif x >= width * 16 or y >= height * 16:
                issues.append('review')
            if kind in PRIMARY_TYPES and record >= 30:
                issues.append('error')
    if not any(kind == 0 and enabled and record < 30
               for record, (kind, enabled) in enumerate(zip(types, active))):
        issues.append('error')
    if sum(kind == 0 and enabled for kind, enabled in zip(types, active)) > 8:
        issues.append('error')
    present = [kind for kind, enabled in zip(types, active) if enabled]
    objectives = set(phase['objectives'])
    if not objectives.intersection((1, 2, 3, 5, 8)):
        issues.append('error')
    if objectives.intersection((6, 7)) and not {1, 2}.issubset(objectives):
        issues.append('error')
    if 1 in objectives and not ENEMY_TYPES.intersection(present):
        issues.append('review')
    if 2 in objectives and not BUILDING_TYPES.intersection(present):
        issues.append('review')
    if 6 in objectives:
        issues.append('review')
    if 7 in objectives and not {0x6C, 0x6D, 0x6E}.intersection(present):
        issues.append('error')
    if objectives.intersection((3, 5)):
        if not {0x48, 0x6A}.intersection(present):
            issues.append('error')
        if 0x49 not in present:
            issues.append('error')
        if present.count(0x49) > 1:
            issues.append('review')
    if 8 in objectives:
        if 0x5A not in present:
            issues.append('error')
        issues.append('review')
    if phase['countdown'] is not None and phase['overview']:
        issues.append('error')
    issues.append('review')     # only a test play shows that a phase can be won
    return issues


def validate_mission(manifest_name: str, manifest_bytes: bytes, files: dict) -> dict:
    """Decode a mission and check every file it references. Returns the
    manifest, the physical file names of its phases and its issues."""
    manifest = decode_manifest(manifest_bytes, manifest_name)
    names = {}
    for name in files:
        if name.lower() in names:
            raise ValueError('case-colliding inventory filenames')
        names[name.lower()] = name
    phases, issues = [], []
    for index, phase in enumerate(manifest['phases']):
        payloads = {}
        for kind in ('map', 'spt'):
            reference = phase[kind]
            name = names.get(reference['name'])
            if name is None:
                raise ValueError(f'phase {index}: missing {reference["name"]}')
            data = files[name]
            if len(data) != reference['length']:
                raise ValueError(f'phase {index}: {kind} length mismatch')
            if zlib.crc32(data) != int(reference['crc32'], 16):
                raise ValueError(f'phase {index}: {kind} CRC mismatch')
            payloads[kind] = name
        level = decode_map(files[payloads['map']])
        if level['width'] * level['height'] > 7500:
            raise ValueError(f'phase {index}: MAP exceeds 7500 cells')
        pair = tuple(name[:-4] if name.endswith('.blk') else name for name in level['tilesets'])
        if pair not in RESOURCE_PAIRS:
            raise ValueError(f'phase {index}: unsupported terrain resource pair')
        objects = decode_spt(files[payloads['spt']])
        if any(obj['type'] > 0x6E for obj in objects):
            raise ValueError(f'phase {index}: SPT type outside 00..6E')
        issues += gameplay_issues(phase, level, objects)
        phases.append((payloads['map'], payloads['spt']))
    return {'manifest': manifest, 'phases': phases, 'issues': issues}


def complete_missions(files: dict[str, bytes]) -> dict[str, bytes]:
    """Every file must belong to a complete mission; names in lower case."""
    normalized = {}
    for name, data in files.items():
        if not re.fullmatch(r'[0-9A-Fa-f]{8}(?:\.[cC][mM][iI]|[0-9A-Fa-f]{2}\.(?:[mM][aA][pP]|[sS][pP][tT]))',
                            name):
            raise ValueError('unexpected mission filename or payload type')
        if name.lower() in normalized:
            raise ValueError('case-colliding mission filenames')
        normalized[name.lower()] = data
    used, result = set(), {}
    for name in sorted(name for name in normalized if name.endswith('.cmi')):
        mission = validate_mission(name, normalized[name], normalized)
        for phase in mission['manifest']['phases']:
            for kind in ('map', 'spt'):
                reference = phase[kind]['name']
                result[reference] = normalized[reference]
                used.add(reference)
        # Each manifest follows its phases, as the editor writes them.
        result[name] = normalized[name]
        used.add(name)
    if used != set(normalized):
        raise ValueError('unreferenced or incomplete mission generation')
    return result


def units(files: dict[str, bytes]) -> int:
    return sum((len(data) + UNIT_BYTES - 1) // UNIT_BYTES for data in files.values())


def read_directory(path: Path) -> dict[str, bytes]:
    """A flat directory of plain files, as the game's directory cache holds it."""
    if path.is_symlink() or not path.is_dir():
        raise ValueError('not a directory: ' + str(path))
    files, names = {}, set()
    for entry in sorted(path.iterdir()):
        if (entry.is_symlink() or not entry.is_file() or not valid_name(entry.name)
                or entry.name.lower() in names):
            raise ValueError('invalid, linked or case-colliding directory entry: ' + entry.name)
        data = entry.read_bytes()
        if not 1 <= len(data) <= 65535:
            raise ValueError('file size outside custom directory bounds: ' + entry.name)
        files[entry.name] = data
        names.add(entry.name.lower())
    if len(files) > DIRECTORY_LIMIT:
        raise ValueError(f'directory exceeds {DIRECTORY_LIMIT} records')
    return files


def read_custom(path: Path) -> dict[str, bytes]:
    """An install's Custom directory, with its editor marker checked."""
    files = read_directory(path)
    folded = {name.lower(): name for name in files}
    if CAMPAIGN_MARKER.lower() in folded:
        raise ValueError('a campaign save disk marker is not allowed in Custom')
    if MARKER_NAME.lower() not in folded:
        raise ValueError('the editor marker CFEDITOR is missing')
    decode_marker(files[folded[MARKER_NAME.lower()]])
    return files


def mission_inventory(files: dict[str, bytes]) -> dict:
    marker = next(data for name, data in files.items() if name.lower() == MARKER_NAME.lower())
    rows = []
    for name, data in files.items():
        if not name.lower().endswith('.cmi'):
            continue
        try:
            mission = validate_mission(name, data, files)
            manifest = mission['manifest']
            errors = mission['issues'].count('error')
            rows.append(dict(file=name, id=manifest['id'], title=manifest['title'],
                             revision=manifest['revision'], phases=len(mission['phases']),
                             state='INVALID' if errors else 'REVIEW', errors=errors,
                             reviews=mission['issues'].count('review')))
        except ValueError as error:
            rows.append(dict(file=name, state='INCOMPLETE', error=str(error)))
    return dict(name=decode_marker(marker), records=len(files),
                free_records=DIRECTORY_LIMIT - len(files),
                free_quota_bytes=max(0, QUOTA_UNITS - units(files)) * UNIT_BYTES,
                files=[dict(name=name, bytes=len(data)) for name, data in files.items()],
                missions=rows)


def export_mission(files: dict[str, bytes], name: str) -> dict[str, bytes]:
    physical = next((item for item in files if item.lower() == name.lower()), None)
    if physical is None or not physical.lower().endswith('.cmi'):
        raise ValueError('select one mission by its .cmi filename')
    mission = validate_mission(physical, files[physical], files)
    result = {}
    for map_name, spt_name in mission['phases']:
        result[map_name], result[spt_name] = files[map_name], files[spt_name]
    result[physical] = files[physical]
    return complete_missions(result)


def prepare_import(files: dict[str, bytes], package: Path) -> dict[str, bytes]:
    """The files to add: no name clashes, within the 150 files and the quota."""
    incoming = complete_missions(read_directory(package))
    if sum(name.endswith('.cmi') for name in incoming) != 1:
        raise ValueError('import requires exactly one complete mission generation')
    clashes = {name.lower() for name in files}.intersection(incoming)
    if clashes:
        raise ValueError('mission filenames already exist: ' + ', '.join(sorted(clashes)))
    if len(files) + len(incoming) > DIRECTORY_LIMIT:
        raise ValueError(f'import exceeds {DIRECTORY_LIMIT} directory records')
    if units(files) + units(incoming) > QUOTA_UNITS:
        raise ValueError('import exceeds the Custom quota')
    return incoming


def publish(root: Path, files: dict[str, bytes], *, new_root: bool) -> None:
    """Create every file (never replace one) and read it back. On a failure
    only the files and directories this call created are removed."""
    for name in files:
        parts = Path(name).parts
        if not parts or Path(name).is_absolute() or any(p in ('', '.', '..') for p in parts) or len(parts) > 2:
            raise ValueError('invalid output filename: ' + name)
    if new_root:
        if root.exists() or root.is_symlink():
            raise ValueError('the output must be a new directory: ' + str(root))
    elif root.is_symlink() or not root.is_dir():
        raise ValueError('not a directory: ' + str(root))
    created_files, created_dirs = [], []
    try:
        if new_root:
            root.mkdir()
            created_dirs.append(root)
        for name, data in files.items():
            path = root / name
            if not path.parent.exists():
                path.parent.mkdir()
                created_dirs.append(path.parent)
            with path.open('xb') as stream:
                created_files.append(path)
                stream.write(data)
            if path.read_bytes() != data:
                raise OSError('the file reads back differently: ' + name)
    except BaseException:
        for path in reversed(created_files):
            path.unlink(missing_ok=True)
        for path in reversed(created_dirs):
            try:
                path.rmdir()
            except OSError:
                pass
        raise


def missions_main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(prog='patch.py', description='List, export or import custom missions.')
    commands = parser.add_subparsers(dest='command', required=True)
    listing = commands.add_parser('list', help='show the missions in a Custom directory')
    listing.add_argument('custom', type=Path)
    exporting = commands.add_parser('export', help='copy one complete mission to a new directory')
    exporting.add_argument('custom', type=Path)
    exporting.add_argument('mission', help="the mission's .cmi filename, as shown by list")
    exporting.add_argument('--output', type=Path, required=True)
    importing = commands.add_parser('import', help='add an exported mission to a Custom directory')
    importing.add_argument('custom', type=Path)
    importing.add_argument('package', type=Path, help='a directory created by export')
    args = parser.parse_args(argv)
    try:
        files = read_custom(args.custom)
        if args.command == 'list':
            print(json.dumps(mission_inventory(files), indent=2))
        elif args.command == 'export':
            publish(args.output, export_mission(files, args.mission), new_root=True)
            print('Created ' + str(args.output.resolve()))
        else:
            incoming = prepare_import(files, args.package)
            publish(args.custom, incoming, new_root=False)
            print('Added ' + ', '.join(sorted(incoming)) + ' to ' + str(args.custom.resolve()))
    except (OSError, ValueError, KeyError, TypeError) as error:
        parser.exit(1, 'Error: ' + str(error) + '\n')
    return 0


def main(argv: list[str] | None = None) -> int:
    argv = sys.argv[1:] if argv is None else list(argv)
    if argv and argv[0] in ('list', 'export', 'import'):
        return missions_main(argv)
    parser = argparse.ArgumentParser(prog='patch.py', description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('disks', type=Path, nargs=3, help='the images of the three disks')
    parser.add_argument('--output', type=Path, default=Path('CannonFodder'),
                        help='the new install directory (default: CannonFodder)')
    parser.add_argument('--name', default='CUSTOM LEVELS',
                        help='the name the editor shows for Custom, up to 31 characters')
    args = parser.parse_args(argv)
    try:
        # Every input is checked before any file is written.
        files = prepare_install(verified_disks(args.disks), args.name)
        publish(args.output, files, new_root=True)
    except (OSError, ValueError, KeyError, TypeError) as error:
        parser.exit(1, 'Error: ' + str(error) + '\n')
    print('Created ' + str(args.output.resolve()))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
